/// Mutable error-attribution state shared across an in-memory
/// [DartObjectDecoder] subtree (and optional streaming `mapped()` handoff).
final class DartObjectErrorState {
  List<Object> containerPath;
  bool hasLeaf = false;
  Object? leaf;
  CodableException? attributedError;

  DartObjectErrorState([this.containerPath = const []]);

  void setContainer(List<Object> path) {
    containerPath = path;
    hasLeaf = false;
    leaf = null;
  }

  void setLeaf(List<Object> container, Object segment) {
    containerPath = container;
    hasLeaf = true;
    leaf = segment;
  }

  List<Object> buildLeafPath() =>
      hasLeaf ? <Object>[...containerPath, leaf!] : containerPath;

  CodableException record(CodableException error) {
    attributedError = error;
    return error;
  }
}

Never _throwDartObjectError(
  String message, {
  List<Object> path = const [],
  Object? actualValue,
  Object? underlyingError,
  DartObjectErrorState? errorState,
}) {
