Uint8List _decodeByteListFromObjects(
  List<Object?> v, {
  List<Object> path = const [],
  DartObjectErrorState? errorState,
}) {
  final out = Uint8List(v.length);
  for (var i = 0; i < v.length; i++) {
    final e = v[i];
    if (e is! int || e < 0 || e > 255) {
      _throwDartObjectError(
        'Expected byte 0..255 in list, found $e',
        path: <Object>[...path, i],
        actualValue: _diagnosticScalar(e),
        errorState: errorState,
      );
    }
    out[i] = e;
  }
  return out;
}

