  ValueKind peekKind() => _dartObjectToValueKind(
    _peekCurrentValue(),
    path: _currentValuePath(),
    errorState: _errorState,
  );

  bool isNextNull() => _hasCurrentValue() && _peekCurrentValue() == null;

  void readNull() {
    final v = _peekCurrentValue();
    if (v != null) _failValue('null', v);
    _commitCurrentValue();
