    _failValue('double', v);
  }

  num readNum() {
    final v = _peekCurrentValue();
    if (v is num) {
      _commitCurrentValue();
      return v;
    }
    _failValue('num', v);
  }

  String readString() {
    final v = _peekCurrentValue();
    if (v is String) {
      _commitCurrentValue();
      return v;
    }
    _failValue('String', v);
  }

  bool readBool() {
    final v = _peekCurrentValue();
    if (v is bool) {
      _commitCurrentValue();
      return v;
    }
    _failValue('bool', v);
  }

  Uint8List readBytes() {
    final v = _peekCurrentValue();
    final bytes = _decodeObjectBytes(
      v,
      path: _currentValuePath(),
      errorState: _errorState,
