/// Sequential [KeyedDecoder] over a parsed `Map<String, Object?>`.
final class DartObjectKeyedDecoder
    with BaseKeyedDecoderMixin, _DartObjectSequentialMixin
    implements KeyedDecoder {
  final Map<String, Object?> _map;
  @override
  final Map<Object, Object?> _userInfo;
  final List<Object> _path;
  @override
  final DartObjectErrorState? _errorState;
  late final List<String> _keys = _map.keys.toList(growable: false);
  int _index = 0;
  String? _activeKey;
  String? _lastKey;
  Object? _activeValue;
  bool _hasActive = false;

  DartObjectKeyedDecoder(
    this._map,
    this._userInfo, {
    this._path = const [],
    this._errorState,
  });

  @override
  List<Object> _currentValuePath() =>
      _lastKey != null ? <Object>[..._path, _lastKey!] : _path;

  @override
  bool moveNextKey() {
    if (_hasActive) return true;
    if (_index >= _keys.length) {
      _lastKey = null;
      _errorState?.setContainer(_path);
      return false;
    }
    final key = _keys[_index++];
    _activeKey = key;
    _lastKey = key;
    _activeValue = _map[key];
    _hasActive = true;
    _errorState?.setLeaf(_path, key);
    return true;
  }

  @override
  bool _hasCurrentValue() => moveNextKey();

  @override
  Object? _peekCurrentValue() {
    if (!moveNextKey()) {
      _throwDartObjectError(
        'No more keys in object',
        path: _path,
        errorState: _errorState,
      );
    }
    _errorState?.setLeaf(_path, _lastKey!);
    return _activeValue;
  }

  @override
  void _commitCurrentValue() {
    _hasActive = false;
    _activeKey = null;
    _activeValue = null;
  }

  @override
  String nextKey() {
    if (!moveNextKey()) {
      _throwDartObjectError(
        'No more keys in object',
        path: _path,
        errorState: _errorState,
      );
    }
    return _activeKey!;
  }

  @override
  String? peekKey() => moveNextKey() ? _activeKey : null;

  @override
  int selectKeyIndex(KeyOptions options) =>
      moveNextKey() ? options.indexOf(_activeKey!) : -1;

  @override
  void skipValue() {
    if (moveNextKey()) _commitCurrentValue();
  }
}

/// Sequential [MapDecoder] over a parsed `Map<String, Object?>`.
final class DartObjectMapDecoder implements MapDecoder {
  final Map<String, Object?> _map;
  final Map<Object, Object?> _userInfo;
  final List<Object> _path;
  final DartObjectErrorState? _errorState;
  late final List<String> _keys = _map.keys.toList(growable: false);
  late final StringMapKeyDecoder _keyDecoder = StringMapKeyDecoder(
    _userInfo,
    onError: _enrichKeyError,
  );
  int _index = 0;
  String? _currentKey;
  Object? _currentValue;
  bool _hasCurrent = false;

  DartObjectMapDecoder(
    this._map,
    this._userInfo, {
    this._path = const [],
    this._errorState,
  });

  CodableException _enrichKeyError(CodableException e) {
    final keyPath = _currentKey != null
        ? List<Object>.unmodifiable(<Object>[..._path, _currentKey!])
        : List<Object>.unmodifiable(_path);
    final enriched = CodableException(
      e.message,
      path: keyPath,
      actualValue: e.actualValue,
      underlyingError: e.underlyingError,
    );
    _errorState?.record(enriched);
    return enriched;
  }

  @override
  int? get length => _map.length;

  @override
  bool moveNextEntry() {
    if (_index >= _keys.length) {
      _hasCurrent = false;
      _currentKey = null;
      _errorState?.setContainer(_path);
      return false;
    }
    final key = _keys[_index++];
    _currentKey = key;
    _keyDecoder.key = key;
    _currentValue = _map[key];
    _hasCurrent = true;
    _errorState?.setLeaf(_path, key);
    return true;
  }

  @override
  Decoder keyDecoder() {
    if (!_hasCurrent) {
      _throwDartObjectError(
        'No active map entry',
        path: _path,
        errorState: _errorState,
      );
    }
    _errorState?.setLeaf(_path, _currentKey!);
    return _keyDecoder;
  }

  @override
  Decoder valueDecoder() {
    if (!_hasCurrent) {
      _throwDartObjectError(
        'No active map entry',
        path: _path,
        errorState: _errorState,
      );
    }
    final nextPath = <Object>[..._path, _currentKey!];
    _errorState?.setContainer(nextPath);
    return DartObjectDecoder(
      _currentValue,
      userInfo: _userInfo,
      path: nextPath,
      errorState: _errorState,
    );
  }
}

/// Sequential [UnkeyedDecoder] over a parsed `List<Object?>`.
final class _DartObjectUnkeyedDecoder
    with BaseUnkeyedDecoderMixin, _DartObjectSequentialMixin
    implements UnkeyedDecoder {
  final List<Object?> _list;
  @override
  final Map<Object, Object?> _userInfo;
  final List<Object> _path;
  @override
  final DartObjectErrorState? _errorState;
  int _index = 0;
  int _lastIndex = -1;
  bool _hasActive = false;

  _DartObjectUnkeyedDecoder(
    this._list,
    this._userInfo, {
    this._path = const [],
    this._errorState,
  });

  @override
  List<Object> _currentValuePath() =>
      _lastIndex >= 0 ? <Object>[..._path, _lastIndex] : _path;

  @override
  int? get length => _list.length;

  @override
  bool moveNext() {
    if (_hasActive) return true;
    if (_index >= _list.length) {
      _lastIndex = -1;
      _errorState?.setContainer(_path);
      return false;
    }
    _lastIndex = _index;
    _hasActive = true;
    _errorState?.setLeaf(_path, _index);
    return true;
  }

  @override
  bool _hasCurrentValue() => moveNext();

  @override
  Object? _peekCurrentValue() {
    if (!moveNext()) {
      _throwDartObjectError(
        'No more elements in array',
        path: _path,
        errorState: _errorState,
      );
    }
    _errorState?.setLeaf(_path, _index);
    return _list[_index];
  }

  @override
  void _commitCurrentValue() {
    _hasActive = false;
    _index++;
  }

  @override
  void skipElement() {
    _takeCurrentValue();
  }
}

